package de.local.tapoviewer;

import android.app.AlertDialog;
import android.content.Intent;
import android.os.Bundle;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;

public final class BackupActivity extends ViewerActivity {
    private EditText password;private Switch accounts;private TextView status;private char[] pendingPassword;private boolean pendingAccounts;
    private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
    private BackupTransfer transfer;private AlertDialog transferDialog;private char[] transferSecret;
    private final android.os.Handler transferUi=new android.os.Handler(android.os.Looper.getMainLooper());
    private final Runnable transferTimeout=()->{closeTransfer();status.setText("Übertragung nach zehn Minuten geschlossen");};
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=Ui.page(this,"Sicherung & Wiederherstellung");ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout form=Ui.column(this);scroll.addView(form);
        Ui.add(form,Ui.text(this,"Die Sicherungsdatei wird immer mit AES-256-GCM und einem eigenen Passwort verschlüsselt. Bewahre das Passwort sicher auf: ohne dieses Passwort ist keine Wiederherstellung möglich. Aufnahmen und Fotos sind nicht enthalten.",15,ViewerStyle.MUTED),-2);
        password=Ui.field(form,"Sicherungspasswort (mindestens 10 Zeichen)","",true);accounts=Ui.toggle(form,"Kamera-Zugangsdaten und vollständige Stream-URLs einschließen",false);
        Ui.add(form,Ui.button(this,"Sicherung auf Receiver und in Downloads speichern",this::saveDirect),48);
        Ui.add(form,Ui.button(this,"Gespeicherte Receiver-Sicherung wiederherstellen",this::restoreLocal),48);
        Ui.add(form,Ui.button(this,"Sicherung auf Handy / PC herunterladen",this::downloadToBrowser),48);
        Ui.add(form,Ui.button(this,"Sicherung vom Handy / PC übertragen",this::uploadFromBrowser),48);
        Ui.add(form,Ui.button(this,"Sicherung an anderem Ort speichern …",()->pick(true)),48);Ui.add(form,Ui.button(this,"Externe Sicherungsdatei öffnen …",()->pick(false)),48);
        status=Ui.text(this,"Kameras werden nach ID zusammengeführt; andere Einträge bleiben erhalten. Externe Sicherungen können im Heimnetz direkt über den Browser am Handy oder PC übertragen werden – ohne TV-Dateimanager. Für USB-Dateien ist alternativ die Dokumentenauswahl vorgesehen.",14,ViewerStyle.MUTED);Ui.add(form,status,-2);setContentView(root);}
    private boolean passwordReady(){if(password.length()<10){password.setError("Sicherungspasswort mit mindestens 10 Zeichen eingeben");return false;}return true;}
    private void downloadToBrowser(){if(!passwordReady())return;char[] secret=password.getText().toString().toCharArray();boolean include=accounts.isChecked();status.setText("Verschlüsselte Sicherung wird vorbereitet …");worker.submit(()->{try{byte[] encrypted=BackupCodec.encrypt(exportJson(include),secret);runOnUiThread(()->{if(!isFinishing())showTransfer(encrypted,null);});}catch(Exception e){runOnUiThread(()->status.setText("Sicherung konnte nicht vorbereitet werden"));}finally{Arrays.fill(secret,'\0');}});}
    private void uploadFromBrowser(){if(passwordReady())showTransfer(null,password.getText().toString().toCharArray());}
    private void showTransfer(byte[] download,char[] secret){closeTransfer();String address=NetworkUtil.findLocalIpv4();if(address==null){if(secret!=null)Arrays.fill(secret,'\0');Ui.toast(this,"Receiver hat keine lokale Netzwerkadresse");return;}transferSecret=secret;
        try{transfer=new BackupTransfer(address,download,encrypted->runOnUiThread(()->{char[] pass=transferSecret;transferSecret=null;closeTransfer();if(pass!=null)worker.submit(()->{try{decodeIncoming(encrypted,pass);}catch(Exception e){runOnUiThread(()->status.setText("Sicherung ungültig oder Passwort falsch. Es wurde nichts geändert."));}finally{Arrays.fill(pass,'\0');}});}));TextView text=Ui.text(this,"Diese Adresse am Handy oder PC im selben Heimnetz öffnen:\n\n"+transfer.url()+"\n\nNur während dieses Dialogs aktiv, maximal zehn Minuten. Das Passwort wird nicht übertragen.\n\n"+(download==null?"Datei auswählen und senden. Anschließend die Wiederherstellung hier am Fernseher bestätigen.":"Die verschlüsselte .csb-Datei im Browser herunterladen und sicher aufbewahren."),17,-1);text.setPadding(36,20,36,20);text.setTextIsSelectable(true);transferDialog=new AlertDialog.Builder(this).setTitle(download==null?"Sicherung empfangen":"Sicherung herunterladen").setView(text).setNegativeButton("Übertragung schließen",null).create();transferDialog.setOnDismissListener(d->closeTransfer());transferDialog.show();transferUi.postDelayed(transferTimeout,600000);
        }catch(Exception e){closeTransfer();Ui.toast(this,"Lokale Übertragung konnte nicht gestartet werden");}}
    private void closeTransfer(){transferUi.removeCallbacks(transferTimeout);BackupTransfer current=transfer;transfer=null;if(current!=null)current.close();if(transferSecret!=null){Arrays.fill(transferSecret,'\0');transferSecret=null;}AlertDialog dialog=transferDialog;transferDialog=null;if(dialog!=null)dialog.dismiss();}
    private void saveDirect(){if(password.length()<10){password.setError("Mindestens 10 Zeichen");return;}char[] secret=password.getText().toString().toCharArray();boolean include=accounts.isChecked();status.setText("Verschlüsselte Sicherung wird erstellt …");worker.submit(()->{try{boolean exported=BackupFiles.save(this,BackupCodec.encrypt(exportJson(include),secret));runOnUiThread(()->status.setText(exported?"Sicherung auf Receiver und unter Download/camera streamer gespeichert":"Sicherung auf Receiver gespeichert; Download-Export nicht verfügbar"));}catch(Exception e){runOnUiThread(()->status.setText("Sicherung konnte nicht gespeichert werden"));}finally{Arrays.fill(secret,'\0');}});}
    private void restoreLocal(){if(password.length()<10){password.setError("Sicherungspasswort eingeben");return;}List<File> files=BackupFiles.list(this);if(files.isEmpty()){Ui.toast(this,"Noch keine Receiver-Sicherung vorhanden");return;}String[] names=new String[files.size()];for(int i=0;i<names.length;i++)names[i]=files.get(i).getName();new AlertDialog.Builder(this).setTitle("Sicherung auswählen").setItems(names,(d,n)->{if(pendingPassword!=null)Arrays.fill(pendingPassword,'\0');pendingPassword=password.getText().toString().toCharArray();onActivityResult(11,RESULT_OK,new Intent().setData(android.net.Uri.fromFile(files.get(n))));}).show();}
    private void pick(boolean export){if(password.length()<10){password.setError("Mindestens 10 Zeichen");return;}if(pendingPassword!=null)Arrays.fill(pendingPassword,'\0');pendingPassword=password.getText().toString().toCharArray();pendingAccounts=accounts.isChecked();Intent intent=new Intent(export?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(export?"application/octet-stream":"*/*");if(export)intent.putExtra(Intent.EXTRA_TITLE,"camera-streamer-backup.csb");android.content.pm.ResolveInfo picker=getPackageManager().resolveActivity(intent,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY);if(picker!=null&&picker.activityInfo.packageName.contains("frameworkpackagestubs")){clearPassword();Ui.toast(this,"Auf diesem Receiver fehlt eine echte Dokumentenauswahl. Nutze die direkte Receiver-Sicherung oder installiere einen Dokumenten-Dateimanager für externe Dateien.");return;}try{startActivityForResult(intent,export?10:11);}catch(Exception e){Arrays.fill(pendingPassword,'\0');pendingPassword=null;Ui.toast(this,"Keine Dateiauswahl installiert. Bitte einen Android-TV-Dateimanager mit Dokumentenauswahl installieren.");}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){clearPassword();return;}android.net.Uri uri=data.getData();char[] secret=pendingPassword;pendingPassword=null;if(secret==null)return;status.setText("Sicherung wird verarbeitet …");
        if(request==10)worker.submit(()->{try{byte[] bytes=BackupCodec.encrypt(exportJson(pendingAccounts),secret);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(bytes);}runOnUiThread(()->status.setText("Verschlüsselte Sicherung gespeichert"));}catch(Exception e){runOnUiThread(()->status.setText("Sicherung konnte nicht gespeichert werden"));}finally{Arrays.fill(secret,'\0');}});
        else worker.submit(()->{try{byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>4*1024*1024)throw new IOException();out.write(buffer,0,n);}bytes=out.toByteArray();}decodeIncoming(bytes,secret);}catch(Exception e){runOnUiThread(()->status.setText("Sicherung ungültig oder Passwort falsch. Es wurde nichts geändert."));}finally{Arrays.fill(secret,'\0');}});
    }
    private void decodeIncoming(byte[] bytes,char[] secret)throws Exception{JSONObject backup=new JSONObject(BackupCodec.decrypt(bytes,secret));validate(backup);runOnUiThread(()->{if(isFinishing()||isDestroyed())return;new AlertDialog.Builder(this).setTitle("Sicherung übernehmen?").setMessage("Kameraeinträge, Ansichten und Einstellungen werden zusammengeführt. Enthaltene Zugangsdaten ersetzen die Konten derselben Kamera. Bestehende Aufnahmen bleiben erhalten. Automatisches Löschen ist nach der Wiederherstellung deaktiviert.").setNegativeButton("Abbrechen",(d,w)->status.setText("Wiederherstellung abgebrochen")).setPositiveButton("Wiederherstellen",(d,w)->worker.submit(()->{try{restore(backup);runOnUiThread(()->status.setText("Sicherung wiederhergestellt"));}catch(Exception e){runOnUiThread(()->status.setText("Wiederherstellung fehlgeschlagen. Bitte Einstellungen prüfen."));}})).show();});}
    private String exportJson(boolean include)throws Exception{return BackupData.export(this,include);}
    static void validate(JSONObject backup)throws Exception {
        if(backup.getInt("version")!=1)throw new IllegalArgumentException("Unbekannte Version");
        JSONObject settings=backup.getJSONObject("settings");
        Set<String> booleans=new HashSet<>(Arrays.asList("setup_complete","keep_awake","recover","favorites_only","auto_scroll","stream_info_enabled"));
        Set<String> integers=new HashSet<>(Arrays.asList("tile_count","scroll_seconds","stream_info_seconds"));
        Iterator<String> keys=settings.keys();
        while(keys.hasNext()){String key=keys.next();Object value=settings.get(key);if(booleans.contains(key)&&!(value instanceof Boolean))throw new IllegalArgumentException();if(integers.contains(key)&&!(value instanceof Number))throw new IllegalArgumentException();if((key.startsWith("option_")||key.equals("cameras")||key.equals("camera_viewports"))&&!(value instanceof String))throw new IllegalArgumentException();}
        if(settings.has("tile_count")&&!Arrays.asList(1,2,-2,4,6,9,16).contains(settings.getInt("tile_count")))throw new IllegalArgumentException("Ungültiges Raster");
        JSONArray cameras=new JSONArray(settings.getString("cameras"));if(cameras.length()>256)throw new IllegalArgumentException();
        Set<String> ids=new HashSet<>();
        for(int i=0;i<cameras.length();i++){
            JSONObject c=cameras.getJSONObject(i);String id=c.getString("id"),ip=c.getString("ip");
            if(id.isEmpty()||id.length()>256||!ip.matches("[a-zA-Z0-9._-]+")||!ids.add(id))throw new IllegalArgumentException("Ungültige Kamera");
            if(c.optInt("port",554)<1||c.optInt("port",554)>65535)throw new IllegalArgumentException("Ungültiger Port");
            if(!Arrays.asList("RTSP","ONVIF","HLS","MJPEG").contains(c.optString("protocol","RTSP")))throw new IllegalArgumentException("Unbekannte Anbindung");
        }
        JSONArray accounts=backup.getJSONArray("accounts");if(accounts.length()>256)throw new IllegalArgumentException();Set<String> accountIds=new HashSet<>();
        for(int i=0;i<accounts.length();i++){JSONObject account=accounts.getJSONObject(i);String id=account.getString("id");if(!ids.contains(id)||!accountIds.add(id))throw new IllegalArgumentException();if(account.has("user"))for(String field:new String[]{"user","pass","url","suburl"})if(!(account.get(field) instanceof String))throw new IllegalArgumentException();}
        JSONArray views=new JSONArray(settings.optString("option_views","[]"));if(views.length()>30)throw new IllegalArgumentException();for(int i=0;i<views.length();i++){JSONObject view=views.getJSONObject(i);if(view.getString("name").isEmpty()||view.getJSONArray("ids").length()>256||!Arrays.asList(1,2,-2,4,6,9,16).contains(view.getInt("layout")))throw new IllegalArgumentException();}
        JSONObject positions=new JSONObject(settings.optString("camera_viewports","{}"));Iterator<String> names=positions.keys();while(names.hasNext())validatePosition(positions.getJSONObject(names.next()));
        JSONObject named=new JSONObject(settings.optString("option_positions","{}"));names=named.keys();while(names.hasNext()){JSONObject entries=named.getJSONObject(names.next());if(entries.length()>32)throw new IllegalArgumentException();Iterator<String> labels=entries.keys();while(labels.hasNext())validatePosition(entries.getJSONObject(labels.next()));}
    }
    private static void validatePosition(JSONObject view)throws Exception{int zoom=view.getInt("zoom");double x=view.getDouble("x"),y=view.getDouble("y");if(zoom<0||zoom>5||Double.isNaN(x)||Double.isInfinite(x)||Double.isNaN(y)||Double.isInfinite(y)||Math.abs(x)>1||Math.abs(y)>1)throw new IllegalArgumentException("Ungültiger Bildausschnitt");}
    private void restore(JSONObject backup)throws Exception{BackupData.restore(this,backup);}
    private void clearPassword(){if(pendingPassword!=null){Arrays.fill(pendingPassword,'\0');pendingPassword=null;}}
    @Override protected void onStop(){closeTransfer();super.onStop();}
    @Override public void onDestroy(){closeTransfer();clearPassword();worker.shutdown();super.onDestroy();}
}
